func jump(nums []int) int {
    steps := 0
    curEnd := 0
    maxReach := 0
    // 不遍历最后一个位置，到达终点即可
    for i := 0; i < len(nums)-1; i++ {
        if i+nums[i] > maxReach {
            maxReach = i + nums[i]
        }
        if i == curEnd {
            steps++
            curEnd = maxReach
        }
    }
    return steps
}
